import androidx.compose.ui.tooling.preview.Preview
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import uqac.catwalk.ui.theme.CatwalkTheme

class CatListActivity : ComponentActivity() {
 override fun onCreate(savedInstanceState: Bundle?) {
 super.onCreate(savedInstanceState)
 enableEdgeToEdge()
 setContent {
 CatwalkTheme {
 Scaffold(modifier = Modifier.fillMaxSize()) { innerPadding ->
 CatContent(
 modifier = Modifier.padding(innerPadding)
 )
 }
 }
 }
 }
}

@Composable
fun CatContent(modifier: Modifier = Modifier) {
 val context = LocalContext.current

 // Liste des noms de chats (36 noms pour remplir la grille 3x12)
 val catNames = listOf(
 "Minou", "Whiskers", "Shadow", "Luna", "Felix", "Mittens",
 "Smokey", "Tiger", "Princess", "Max", "Bella", "Charlie",
 "Lucy", "Oliver", "Lily", "Leo", "Chloe", "Milo",
 "Sophie", "Jack", "Molly", "Oscar", "Daisy", "Simba",
 "Coco", "Buddy", "Ruby", "Toby", "Zoe", "Sam",
 "Nala", "Ginger", "Patches", "Oreo", "Snowball", "Jasper"
 )

 Scaffold(
 topBar = {
 AppTopBar(
 coinAmount = 56.toString(),
 context = context,
 modifier = Modifier
 .windowInsetsPadding(WindowInsets.statusBars)
 .height(80.dp)
 )
 },

 content = { paddingValues ->
 Box(
 modifier = modifier
 .padding(
 start = paddingValues.calculateStartPadding(LocalLayoutDirection.current),
 top = 80.dp,
 end = paddingValues.calculateEndPadding(LocalLayoutDirection.current),
 bottom = 100.dp
 )
 .fillMaxSize()
 ) {
 // Grillage de chats
 Column(
 modifier = Modifier
 .fillMaxSize()
 .padding(start = 16.dp, end = 16.dp)
 ) {
 Text(
 text = "Nos Chats ",
 style = MaterialTheme.typography.headlineMedium,
 fontWeight = FontWeight.Bold,
 modifier = Modifier
 .fillMaxWidth()
 .padding(
 top = 16.dp,
 bottom = 16.dp
 ),
 textAlign = TextAlign.Center
 )

 LazyVerticalGrid(
 columns = GridCells.Fixed(3),
 verticalArrangement = Arrangement.spacedBy(8.dp),
 horizontalArrangement = Arrangement.spacedBy(8.dp)
 ) {
 items(catNames) { catName ->
 Card(
 modifier = Modifier
 .padding(bottom = 10.dp)
 .height(80.dp)
 .fillMaxWidth(),
 colors = CardDefaults.cardColors(
 containerColor = MaterialTheme.colorScheme.primaryContainer
 ),
 elevation = CardDefaults.cardElevation(defaultElevation = 4.dp)
 ) {
 Box(
 modifier = Modifier.fillMaxSize(),
 contentAlignment = Alignment.Center
 ) {
 Text(
 text = catName,
 textAlign = TextAlign.Center,
 fontSize = 14.sp,
 fontWeight = FontWeight.Medium,
 color = MaterialTheme.colorScheme.onPrimaryContainer
 )
 }
 }
 }
 }
 }
 }
 },

 bottomBar = {
 AppBottomBar(
 context = context,
 modifier = Modifier
 .windowInsetsPadding(WindowInsets.navigationBars)
 .height(100.dp)
 )
 }
 )
}

