// Top bar for every screen that is not the main screen
@Composable
fun AppTopBar(coinAmount: String,
 context: Context,
 modifier: Modifier = Modifier
) {
 Box(
 modifier = modifier,
 ) {
 Row(
 modifier = Modifier
 .background(color = Color.Cyan)
 .fillMaxWidth()
 .fillMaxHeight()
 .drawBehind {
 drawLine(
 color = Color.Black,
 start = Offset(0f, size.height),
 end = Offset(size.width, size.height),
 strokeWidth = 3.dp.toPx()
 )
 },
 verticalAlignment = Alignment.CenterVertically
 ) {
 // Bouton Home en haut à gauche
 Button(
 onClick = {
 val intent = Intent(context, MainActivity::class.java)
 context.startActivity(intent)
 },
 modifier = Modifier
 .padding(start = 5.dp)
 ) {
 Icon(
 imageVector = Icons.Filled.Home,
 contentDescription = "Retour à l'accueil"
 )
 }

 Button(
 onClick = {
 val intent = Intent(context, AchievementsActivity::class.java)
 context.startActivity(intent)
 },
 modifier = Modifier
 .padding(start = 5.dp)
 .fillMaxWidth(1f / 1.5f)
 ) {
 Icon(
 imageVector = Icons.Filled.Favorite,
 contentDescription = "Go to Lv Activity"
 )
 }
 Row(
 modifier = Modifier
 .fillMaxWidth()
 ) {
 Box(
 contentAlignment = Alignment.Center
 ) {
 Text(
 text = coinAmount,
 textAlign = TextAlign.Center,
 fontSize = 25.sp,
 modifier = Modifier
 .size(height = 40.dp, width = 60.dp)
 .offset(40.dp)
 .border(BorderStroke(2.dp, Color.Black))
 .background(color = Color.Yellow)
 .offset(x = 5.dp, y = 5.dp)

 )
 Image(
 painter = painterResource(R.drawable.money_icon),
 contentDescription = "Image de pièce chat",
 modifier = Modifier
 .background(color = Color.White)
 .size(50.dp)
 )
 }
 }

 }
 }
}

@Composable
fun LvContent(modifier: Modifier = Modifier) {
 val context = LocalContext.current
 // Liste des niveaux (15 pour l'exemple)
 val levels = listOf(
 "Niveau 1 - Débutant", "Niveau 2 - Novice", "Niveau 3 - Apprenti",
 "Niveau 4 - Intermédiaire", "Niveau 5 - Avancé", "Niveau 6 - Expert",
 "Niveau 7 - Maître", "Niveau 8 - Grand Maître", "Niveau 9 - Légende",
 "Niveau 10 - Mythique", "Niveau 11 - Divin", "Niveau 12 - Transcendant",
 "Niveau 13 - Éternel", "Niveau 14 - Infini", "Niveau 15 - Ultime"
 )

 Scaffold (
 topBar = {
 AppTopBar(
 56.toString(),
 context,
 modifier = Modifier
 .windowInsetsPadding(WindowInsets.statusBars)
 .height(80.dp)
 )
 },

 content = { paddingValues ->
 Box(
 modifier = modifier
 .padding(
 start = paddingValues.calculateStartPadding(LocalLayoutDirection.current),
 top = 80.dp,
 end = paddingValues.calculateEndPadding(LocalLayoutDirection.current),
 bottom = 100.dp
 )
 .fillMaxSize()
 .background(color = Color.LightGray)
 ) {
 // Liste scrollable des niveaux
 Column(
 modifier = Modifier
 .fillMaxSize()
 .padding(start = 16.dp, end = 16.dp)
 ) {
 Text(
 text = "Achievements",
 style = MaterialTheme.typography.headlineMedium,
 fontWeight = FontWeight.Bold,
 modifier = Modifier
 .fillMaxWidth()
 .padding(
 top = 16.dp,
 bottom = 16.dp
 ),
 textAlign = TextAlign.Center
 )

 LazyColumn(
 verticalArrangement = Arrangement.spacedBy(8.dp)
 ) {
 items(levels) { level ->
 Card(
 modifier = Modifier
 .padding(bottom = 10.dp)
 .height(120.dp)
 .fillMaxWidth(),
 colors = CardDefaults.cardColors(
 containerColor = MaterialTheme.colorScheme.primaryContainer
 ),
 elevation = CardDefaults.cardElevation(defaultElevation = 4.dp)
 ) {
 Box(
 modifier = Modifier.fillMaxSize(),
 contentAlignment = Alignment.Center
 ) {
 Text(
 text = level,
 textAlign = TextAlign.Center,
 fontSize = 18.sp,
 fontWeight = FontWeight.Medium,
 color = MaterialTheme.colorScheme.onPrimaryContainer
 )
 }
 }
 }
 }
 }
 }
 },

 bottomBar = {
 AppBottomBar(
 context,
 modifier = Modifier
 .windowInsetsPadding(WindowInsets.navigationBars)
 .height(100.dp)
 )
 }
 )


}

