package uqac.catwalk

import android.content.Intent
import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import androidx.compose.foundation.Image
import androidx.compose.foundation.background
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.filled.Face
import androidx.compose.material.icons.filled.FavoriteBorder
import androidx.compose.material.icons.filled.Home
import androidx.compose.material.icons.filled.Person
import androidx.compose.material.icons.filled.PlayArrow
import androidx.compose.material.icons.filled.ShoppingCart
import androidx.compose.material.icons.filled.Star
import androidx.compose.material3.*
import androidx.compose.material3.LinearProgressIndicator
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.layout.ContentScale
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.res.painterResource
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.style.TextAlign
import androidx.compose.ui.tooling.preview.Preview
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import uqac.catwalk.sauvegarde.entities.Cat
import uqac.catwalk.ui.theme.CatwalkTheme

class CatInteractionActivity : ComponentActivity() {
 override fun onCreate(savedInstanceState: Bundle?) {
 super.onCreate(savedInstanceState)
 enableEdgeToEdge()
 val cat = if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.TIRAMISU) {
 intent?.getParcelableExtra("cat", Cat::class.java)
 } else {
 @Suppress("DEPRECATION")
 intent?.getParcelableExtra<Cat>("cat")
 }
 setContent {
 CatwalkTheme {
 Scaffold(modifier = Modifier.fillMaxSize()) { innerPadding ->
 CatInteractionContent(
 modifier = Modifier.padding(innerPadding),
 cat = cat
 )
 }
 }
 }
 }
}

@Composable
fun CatInteractionContent(modifier: Modifier = Modifier, cat: Cat?) {
 val context = LocalContext.current

 // Utiliser les valeurs du chat ou des valeurs par défaut
 var proprete by remember { mutableStateOf(cat?.cleanliness ?: 80) }
 var amusement by remember { mutableStateOf(cat?.happiness ?: 60) }
 var affection by remember { mutableStateOf(cat?.affection?.toInt() ?: 2) }

 Box(
 modifier = modifier
 .fillMaxSize()
 .background(Color(0xFFFFFFFF))
 ) {
 // Bouton Home en haut à gauche
 Button(
 onClick = {
 val intent = Intent(context, MainActivity::class.java)
 context.startActivity(intent)
 },
 modifier = Modifier
 .align(Alignment.TopStart)
 .padding(16.dp)
 ) {
 Icon(
 imageVector = Icons.Filled.Home,
 contentDescription = "Retour à l'accueil"
 )
 }

 // Contenu principal
 Column(
 modifier = Modifier
 .fillMaxSize()
 .padding(16.dp)
 .padding(top = 80.dp),
 horizontalAlignment = Alignment.CenterHorizontally,
 verticalArrangement = Arrangement.SpaceBetween
 ) {
 // Nom du chat
 Text(
 text = cat?.name ?: "Chat Inconnu",
 style = MaterialTheme.typography.headlineSmall,
 fontWeight = FontWeight.Bold,
 modifier = Modifier
 .fillMaxWidth()
 .padding(top = 8.dp),
 textAlign = TextAlign.Center
 )

 // Barre d’affection (coeurs)
 Row(
 horizontalArrangement = Arrangement.Center,
 modifier = Modifier
 .fillMaxWidth()
 .padding(top = 16.dp)
 ) {
 repeat(3) { index ->
 val heartIcon = if (index < affection)
 painterResource(R.drawable.ic_heart_full)
 else
 painterResource(R.drawable.ic_heart_empty)
 Image(
 painter = heartIcon,
 contentDescription = "Cœur ${index + 1}",
 modifier = Modifier
 .size(36.dp)
 .padding(4.dp)
 )
 }
 }

 // Image du chat
 Image(
 painter = painterResource(R.drawable.chat),
 contentDescription = "Chat",
 modifier = Modifier
 .size(300.dp)
 .padding(16.dp),
 contentScale = ContentScale.Crop
 )

 // ⚡ Barres côte à côte
 Row(
 horizontalArrangement = Arrangement.SpaceEvenly,
 modifier = Modifier
 .fillMaxWidth()
 .padding(vertical = 24.dp)
