 // Sécurité : si l'ID est invalide, on ne peut rien faire.
 if (catId == -1) {
 // Gérer l'erreur : fermer l'activité, afficher un message, etc.
 finish()
 return
 }

 setContent {
 CatwalkTheme {
 // 2. Récupérer les données du chat depuis la BDD
