@Composable
fun CatInteractionContent(modifier: Modifier = Modifier, cat: Cat?) {
 val context = LocalContext.current

 // Utiliser les valeurs du chat ou des valeurs par défaut
 var proprete by remember { mutableStateOf(cat?.cleanliness ?: 0) }
 var amusement by remember { mutableStateOf(cat?.happiness ?: 0) }
 var affection by remember { mutableStateOf(cat?.affection?.toInt() ?: 0) }

 Box(
 modifier = modifier
 .fillMaxSize()
 .background(Color(0xFFFFFFFF))
 ) {
 // Bouton Home en haut à gauche
 Button(
 onClick = {
 val intent = Intent(context, MainActivity::class.java)
 context.startActivity(intent)
 },
 modifier = Modifier
 .align(Alignment.TopStart)
 .padding(16.dp)
 ) {
 Icon(
 imageVector = Icons.Filled.Home,
 contentDescription = "Retour à l'accueil"
 )
 }

 // Contenu principal
 Column(
 modifier = Modifier
 .fillMaxSize()
 .padding(16.dp)
 .padding(top = 80.dp),
 horizontalAlignment = Alignment.CenterHorizontally,
 verticalArrangement = Arrangement.SpaceBetween
 ) {
 // Nom du chat
 Text(
 text = cat?.name ?: "Chat Inconnu",
 style = MaterialTheme.typography.headlineSmall,
 fontWeight = FontWeight.Bold,
 modifier = Modifier
 .fillMaxWidth()
 .padding(top = 8.dp),
 textAlign = TextAlign.Center
 )

 // Barre d’affection (coeurs)
 Row(
 horizontalArrangement = Arrangement.Center,
 modifier = Modifier
 .fillMaxWidth()
 .padding(top = 16.dp)
 ) {
 repeat(3) { index ->
 val heartIcon = if (index < affection)
 painterResource(R.drawable.ic_heart_full)
 else
 painterResource(R.drawable.ic_heart_empty)
 Image(
 painter = heartIcon,
 contentDescription = "Cœur ${index + 1}",
 modifier = Modifier
 .size(36.dp)
 .padding(4.dp)
 )
 }
 }

 // Image du chat
 Image(
 painter = painterResource(R.drawable.chat),
 contentDescription = "Chat",
 modifier = Modifier
 .size(300.dp)
 .padding(16.dp),
 contentScale = ContentScale.Crop
 )

 // ⚡ Barres côte à côte
 Row(
 horizontalArrangement = Arrangement.SpaceEvenly,
 modifier = Modifier
 .fillMaxWidth()
 .padding(vertical = 24.dp)
 ) {
 Column(horizontalAlignment = Alignment.CenterHorizontally) {
 Text("Propreté", fontWeight = FontWeight.Bold)
 LinearProgressIndicator(
 progress = { proprete / 100f },
 modifier = Modifier
 .width(130.dp)
 .height(10.dp)
 .padding(top = 4.dp),
 color = Color(0xFF4CAF50),
 trackColor = Color(0xFFC8E6C9),
 strokeCap = ProgressIndicatorDefaults.LinearStrokeCap,
 )
 }
 Column(horizontalAlignment = Alignment.CenterHorizontally) {
 Text("Amusement", fontWeight = FontWeight.Bold)
 LinearProgressIndicator(
 progress = { amusement / 100f },
 modifier = Modifier
 .width(130.dp)
 .height(10.dp)
 .padding(top = 4.dp),
 color = Color(0xFFFF9800),
 trackColor = Color(0xFFFFE0B2),
 strokeCap = ProgressIndicatorDefaults.LinearStrokeCap,
 )
 }
 }

 // Footer : boutons d’action
 Row(
 modifier = Modifier
 .fillMaxWidth()
 .height(72.dp) // hauteur fixe et prévisible
 .background(MaterialTheme.colorScheme.primary)
 .padding(vertical = 8.dp)
 .clickable {
 catDao.updateCatHappiness(cat.id, min(cat.happiness + 10,100))
 },
 horizontalArrangement = Arrangement.SpaceEvenly,
 ) {
 // Play section
 Box(
 modifier = Modifier
 .weight(1f)
 .fillMaxHeight(),
 contentAlignment = Alignment.Center
 ) {

 Column(
 horizontalAlignment = Alignment.CenterHorizontally,
 verticalArrangement = Arrangement.Center // centrer verticalement
 ) {
 Icon(
 imageVector = Icons.Filled.Star,
 contentDescription = "Jouer",
 tint = MaterialTheme.colorScheme.onPrimary
 )
 Spacer(modifier = Modifier.height(4.dp))
 Text("Jouer", color = MaterialTheme.colorScheme.onPrimary)
 }
 }

 VerticalDivider(
 color = MaterialTheme.colorScheme.onPrimary.copy(alpha = 0.3f),
 thickness = 1.dp,
 modifier = Modifier
 .fillMaxHeight()
 )

 // wash section
 Box(
 modifier = Modifier
 .weight(1f)
 .fillMaxHeight(),
 contentAlignment = Alignment.Center
 ) {
 Column(
 horizontalAlignment = Alignment.CenterHorizontally,
 verticalArrangement = Arrangement.Center
 ) {
 Icon(
 imageVector = Icons.Filled.PlayArrow,
 contentDescription = "Laver",
 tint = MaterialTheme.colorScheme.onPrimary
 )
 Spacer(modifier = Modifier.height(4.dp))
 Text("Laver", color = MaterialTheme.colorScheme.onPrimary)
 }
 }

 VerticalDivider(
 color = MaterialTheme.colorScheme.onPrimary.copy(alpha = 0.3f),
 thickness = 1.dp,
 modifier = Modifier
 .fillMaxHeight()
 )

 // pet section
 Box(
 modifier = Modifier
 .weight(1f)
 .fillMaxHeight(),
 contentAlignment = Alignment.Center
 ) {
 Column(
 horizontalAlignment = Alignment.CenterHorizontally,
 verticalArrangement = Arrangement.Center
 ) {
 Icon(
 imageVector = Icons.Filled.FavoriteBorder,
 contentDescription = "Caresser",
 tint = MaterialTheme.colorScheme.onPrimary
 )
 Spacer(modifier = Modifier.height(4.dp))
 Text("Caresser", color = MaterialTheme.colorScheme.onPrimary)
 }
 }
 }

 }
 }
}

